function launchSample(p){
 const lp=LAUNCH_PRODUCTS.find(x=>x.id===p.id);
 if(!lp)return '';
 return `<section class="panel detail-copy" id="book-sample"><h2>ดูหน้าจริงในเล่ม</h2><p>ภาพด้านล่างมาจากไฟล์ PDF ฉบับขายจริง</p><div style="display:flex;gap:16px;flex-wrap:wrap"><img src="${lp.image}" alt="ปก ${lp.name}" style="width:260px;max-width:100%;border-radius:12px;box-shadow:0 6px 20px #0002"><img src="${lp.page}" alt="ตัวอย่างหน้าใน ${lp.name}" style="width:260px;max-width:100%;border-radius:12px;box-shadow:0 6px 20px #0002"></div><p class="help">ดูสินค้าทั้งหมดและคลิปแนะนำได้ที่ <a href="/learn/">หน้าแนะนำชุดฝึกอ่านเขียน</a></p></section>`;
}

function refreshKidsReading(products){const previous={"kids-color-story": "ต้นแบบ PDF ไทย-อังกฤษ 20 หน้า: 8 ภาพสัตว์ระบายสี + 8 หน้าวาดต่อ + ส่วนประกอบ 4 หน้า มี A4 และ US Letter เนื้อหาเดียวกัน แนวเริ่มต้นประมาณ 4-7 ปี เลือกตามความพร้อมเด็ก", "kids-add-subtract": "ต้นแบบ PDF ไทย-อังกฤษ 48 หน้า: แบบฝึก 40 หน้า รวม 400 ข้อ พร้อมเฉลย 8 หน้า บวกและลบช่วง 0-10 และ 0-20 มี A4/US Letter เนื้อหาเดียวกัน โจทย์มีซ้ำข้ามหน้าเพื่อทบทวน", "kids-color-numbers": "ต้นแบบชุดรวม 68 หน้า: ระบายสีและวาดต่อ 20 หน้า + แบบฝึกเลข 40 หน้า + เฉลย 8 หน้า เป็นการรวมสองชุดเดิม มี A4 และ US Letter เนื้อหาเดียวกัน"};for(const product of products){if(product.description===previous[product.id]){const next=LAUNCH_PRODUCTS.find(x=>x.id===product.id);if(!next)continue;product.description=next.description;if(product.id==='kids-color-story'&&product.name==='ระบายสี แล้วเล่าเรื่องของหนู')product.name=next.name;}}}
